//				u.SetIgnore(ratecard.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *RateCardUpsertBulk) UpdateNewValues() *RateCardUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(ratecard.FieldID)
			}
			if _, exists := b.mutation.UID(); exists {
				s.SetIgnore(ratecard.FieldUID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(ratecard.FieldCreatedAt)
			}
			if _, exists := b.mutation.PlanID(); exists {
				s.SetIgnore(ratecard.FieldPlanID)
			}
			if _, exists := b.mutation.Meter(); exists {
				s.SetIgnore(ratecard.FieldMeter)
			}
			if _, exists := b.mutation.Mode(); exists {
				s.SetIgnore(ratecard.FieldMode)
			}
			if _, exists := b.mutation.Currency(); exists {
				s.SetIgnore(ratecard.FieldCurrency)
			}
			if _, exists := b.mutation.Tiers(); exists {
				s.SetIgnore(ratecard.FieldTiers)
			}
			if _, exists := b.mutation.EffectiveFrom(); exists {
				s.SetIgnore(ratecard.FieldEffectiveFrom)
			}
			if _, exists := b.mutation.Note(); exists {
				s.SetIgnore(ratecard.FieldNote)
			}
			if _, exists := b.mutation.CreatedBy(); exists {
				s.SetIgnore(ratecard.FieldCreatedBy)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.RateCard.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *RateCardUpsertBulk) Ignore() *RateCardUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *RateCardUpsertBulk) DoNothing() *RateCardUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the RateCardCreateBulk.OnConflict
// documentation for more info.
func (u *RateCardUpsertBulk) Update(set func(*RateCardUpsert)) *RateCardUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&RateCardUpsert{UpdateSet: update})
	}))
	return u
}

// Exec executes the query.
func (u *RateCardUpsertBulk) Exec(ctx context.Context) error {
	if u.create.err != nil {
		return u.create.err
	}
	for i, b := range u.create.builders {
		if len(b.conflict) != 0 {
			return fmt.Errorf("ent: OnConflict was set for builder %d. Set it on the RateCardCreateBulk instead", i)
		}
	}
	if len(u.create.conflict) == 0 {
		return errors.New("ent: missing options for RateCardCreateBulk.OnConflict")
	}
	return u.create.Exec(ctx)
}

// ExecX is like Exec, but panics if an error occurs.
func (u *RateCardUpsertBulk) ExecX(ctx context.Context) {
	if err := u.create.Exec(ctx); err != nil {
		panic(err)
	}
}
